<script setup lang="ts">const {lang}=useLocale(); const {data:reviews}=await useFetch<any[]>('/api/content/reviews'); usePageSeo(computed(()=>lang.value==='ru'?'Отзывы о каталоге Signal SMS':'Signal SMS catalog feedback'),computed(()=>lang.value==='ru'?'Отзывы посетителей о навигации и удобстве каталога.':'Visitor feedback about catalog navigation and usability.'));</script>
<template><div class="shell page"><span class="kicker">Community / Feedback</span><h1>{{lang==='ru'?'Что говорят посетители':'What visitors say'}}</h1><p class="lead">{{lang==='ru'?'Демонстрационная подборка отзывов о дизайне и навигации. Она не используется для рейтинговой микроразметки.':'A sample collection of feedback about design and navigation. It is not used for rating structured data.'}}</p><div class="review-grid"><article v-for="r in reviews" :key="r.id"><div><b>{{r.name}}</b><span>{{'★'.repeat(r.rating)}}{{'☆'.repeat(5-r.rating)}}</span></div><p>{{lang==='ru'?r.textRu:r.textEn}}</p><small>{{new Date(r.date).toLocaleDateString(lang)}}</small></article></div></div></template>
